WITH enriched AS (SELECT id, store_id, product_id, sale_date, units, revenue, CORR(revenue, units) OVER w_recent AS corr_revenue_units, RANK() OVER (ORDER BY revenue DESC NULLS LAST) AS revenue_rank FROM store_sales WINDOW w_recent AS (PARTITION BY store_id)) SELECT CASE WHEN revenue >= 4400 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, DATE_TRUNC('MONTH', sale_date) AS activity_month, ROUND(AVG(revenue), 2) AS avg_revenue, COUNT(*) AS event_count, PERCENTILE_APPROX(revenue, ARRAY(0.25, 0.5, 0.75)) AS revenue_quartiles, PERCENTILE_APPROX(units, ARRAY(0.25, 0.5, 0.75)) AS units_quartiles, SUM(revenue) AS total_revenue FROM enriched GROUP BY revenue_tier, activity_month HAVING event_count < 1 ORDER BY activity_month DESC NULLS FIRST;
